# revise marker sets with corrected sets and inspect exact overlapping offsets
objs2={
'5':{(-1,1),(-1,4),(2,0),(3,2)},
'7':{(1,0),(1,5)},
'8':{(-1,0),(-1,5),(4,1),(4,4)},
'4':{(-1,3),(0,5),(3,-1),(4,4)},
'3':{(-1,0),(-1,2),(0,3),(1,4)},
'1A':{(0,1),(1,6),(3,-1),(4,0)},
'1B':{(2,0),(2,2)},
}
def overlaps(a,b, t_b_minus_a):
 A,B=objs2[a],objs2[b]; d=t_b_minus_a
 # A global coords T_A+a; B global T_A+d+b => matching when a=d+b
 return sorted((p, (p[0]-d[0],p[1]-d[1])) for p in A if (p[0]-d[0],p[1]-d[1]) in B)
from collections import Counter
for a,b in [('7','8'),('8','5'),('5','4'),('4','1A'),('1A','3'),('3','1B')]:
 counts=Counter((ra-rb,ca-cb) for ra,ca in objs2[a] for rb,cb in objs2[b])
 m=max(counts.values()); opts=[d for d,n in counts.items() if n==m]
 print('\n',a,b,'max',m,'opts',opts)
 for d in opts: print(d,overlaps(a,b,d))

shapes={
'5': {(0,c) for c in range(6)} | {(1,0),(1,5),(2,5),(3,3),(3,4),(3,5)},
'7': {(0,c) for c in range(6)},
'8': {(0,c) for c in range(6)} | {(r,c) for r in range(1,4) for c in (1,4)},
'4': {(r,c) for r in range(4) for c in range(5)},
'3': {(0,0),(0,1),(0,2),(1,0),(2,0),(2,4)} | {(3,c) for c in range(5)},
'1A': {(0,0),(1,0),(2,0),(2,6)} | {(3,c) for c in range(7)},
'1B': {(0,0),(0,1),(0,2),(1,0),(1,2)},
}
# candidates edge d T_next - T_prev, all positions relative anchor 4
edge_candidates={
('7','8'):[(2,0)],
('8','5'):[(5,0)],
('5','4'):[(3,-3)], # d T4 - T5 so inverse to chain; handle separately
('4','1A'):[(3,-2),(0,4),(-1,-1)],
('1A','3'):[(3,-4),(4,-3)],
('3','1B'):[(-3,0)],
}
# set absolute bbox positions
T={'4':(11,12)}
T['5']=(8,15) # T4 minus (3,-3)
T['8']=(3,15)
T['7']=(1,15)
# combinations
solutions=[]
for d41 in edge_candidates[('4','1A')]:
 T['1A']=(T['4'][0]+d41[0],T['4'][1]+d41[1])
 for d13 in edge_candidates[('1A','3')]:
  T['3']=(T['1A'][0]+d13[0],T['1A'][1]+d13[1])
  d31=(-3,0)
  T['1B']=(T['3'][0]-3,T['3'][1])
  # test all component colored overlap and marker-body conflict
  overlap=[]
  for i,a in enumerate(shapes):
   for b in list(shapes)[i+1:]:
    sa={(T[a][0]+r,T[a][1]+c) for r,c in shapes[a]}
    sb={(T[b][0]+r,T[b][1]+c) for r,c in shapes[b]}
    if sa&sb: overlap.append((a,b,sa&sb))
  # marker sets globals
  markers={k:{(T[k][0]+r,T[k][1]+c) for r,c in v} for k,v in objs2.items()}
  bodies={k:{(T[k][0]+r,T[k][1]+c) for r,c in v} for k,v in shapes.items()}
  conflicts=[]
  for a in markers:
   for b in bodies:
    if a!=b and markers[a]&bodies[b]: conflicts.append((a,b,markers[a]&bodies[b]))
  # bbox
  allcells=set().union(*bodies.values())
  solutions.append((d41,d13,overlap,conflicts,(min(r for r,c in allcells),max(r for r,c in allcells),min(c for r,c in allcells),max(c for r,c in allcells))))
solutions

T={'7':(1,15),'8':(3,15),'5':(8,15),'4':(11,12),'1A':(14,10),'3':(17,6),'1B':(14,6)}
# all corrected marker sets
markers_correct={
'5':{(-1,1),(-1,4),(2,0),(3,2)},
'7':{(1,0),(1,5)},
'8':{(-1,0),(-1,5),(4,1),(4,4)},
'4':{(-1,3),(0,5),(3,-1),(4,4)},
'3':{(-1,0),(-1,2),(0,3),(1,4)},
'1A':{(0,1),(1,6),(3,-1),(4,0)},
'1B':{(2,0),(2,2)},
}
grid=[[0]*26 for _ in range(26)]
coords={}
for k,ps in shapes.items():
 coords[k]={(T[k][0]+r,T[k][1]+c) for r,c in ps}
 for r,c in coords[k]:
  if grid[r][c]!=0: print('body overlap',k,r,c)
  grid[r][c]={'5':5,'7':7,'8':8,'4':4,'3':3,'1A':1,'1B':1}[k]
markglob={}
for k,ps in markers_correct.items():
 markglob[k]={(T[k][0]+r,T[k][1]+c) for r,c in ps}
 for r,c in markglob[k]:
  if grid[r][c]!=0: print('marker-body conflict',k,r,c,grid[r][c])
  grid[r][c]=2
# summarize overlap marker positions
from collections import defaultdict
mcounts=defaultdict(list)
for k,ps in markglob.items():
 for p in ps:mcounts[p].append(k)
print({p:ks for p,ks in mcounts.items() if len(ks)>1})
print('bounds',min(r for ps in coords.values() for r,c in ps),max(r for ps in coords.values() for r,c in ps),min(c for ps in coords.values() for r,c in ps),max(c for ps in coords.values() for r,c in ps))
print('\n'.join(' '.join(map(str,row)) for row in grid))
